void my_signal_handler(int sig);

// Install custom handler for SIGINT (Ctrl+C)
sighandler_t prev_handler = signal(SIGINT, my_signal_handler);

// Built-in dispositions:
// 1. Ignore the signal
signal(SIGTERM, SIG_IGN);

// 2. Restore default action
signal(SIGQUIT, SIG_DFL);

// Function definition (takes signal number)
void my_signal_handler(int sig) {
    if (sig == SIGINT) {
        // Perform cleanup
    }
}

// Check for error on installation
if (prev_handler == SIG_ERR) {
    // Handle error
}
